export type InferWireSchema<S> = S extends {
    anyOf: readonly (infer V)[];
} ? InferWireSchema<V> : S extends {
    enum: readonly (infer E)[];
} ? E : S extends {
    type: 'string';
} ? string : S extends {
    type: 'integer';
} ? number : S extends {
    type: 'boolean';
} ? boolean : S extends {
    type: 'null';
} ? null : S extends {
    type: 'array';
    items: infer I;
} ? InferWireSchema<I>[] : S extends {
    type: 'object';
    properties: infer P;
    required: readonly (infer R)[];
} ? {
    [K in keyof P as K extends R ? K : never]: InferWireSchema<P[K]>;
} & {
    [K in keyof P as K extends R ? never : K]?: InferWireSchema<P[K]>;
} : never;

